    adds r0,r4,#0x0    @ 0810d794 201c
    bl init_sound_channel_playback_slot      @ 0810d796 fff77bff
    strb r0,[r4,#0xe]                        @ 0810d79a a073
    pop {r4}                                 @ 0810d79c 10bc
    pop {r0}                                 @ 0810d79e 01bc
    bx r0                                    @ 0810d7a0 0047
    .byte  0x00, 0x00

